Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$path=Join-Path (Get-Location) 'docs/modding-script-api.xlsx'
$stream=[IO.File]::Open($path,[IO.FileMode]::Create)
$zip=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create)
try {
$entry=$zip.CreateEntry('[Content_Types].xml')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>
'@)
$writer.Dispose()
$entry=$zip.CreateEntry('_rels/.rels')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>
'@)
$writer.Dispose()
$entry=$zip.CreateEntry('xl/workbook.xml')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Рулсеты" sheetId="1" r:id="rId1"/><sheet name="Скриптинг" sheetId="2" r:id="rId2"/></sheets></workbook>
'@)
$writer.Dispose()
$entry=$zip.CreateEntry('xl/_rels/workbook.xml.rels')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>
'@)
$writer.Dispose()
$entry=$zip.CreateEntry('xl/styles.xml')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font></fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF24476A"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFEAF0F6"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="3" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>
'@)
$writer.Dispose()
$entry=$zip.CreateEntry('xl/worksheets/sheet1.xml')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="62" customWidth="1"/><col min="2" max="2" width="88" customWidth="1"/><col min="3" max="3" width="45" customWidth="1"/></cols><sheetData><row r="1" ht="32" customHeight="1"><c r="A1" s="1" t="inlineStr"><is><t>Наименование</t></is></c><c r="B1" s="1" t="inlineStr"><is><t>Описание</t></is></c><c r="C1" s="1" t="inlineStr"><is><t>Значение по умолчанию</t></is></c></row><row r="2" ht="60" customHeight="1"><c r="A2" s="2" t="inlineStr"><is><t>items[].scripts.inventorySpriteOverlay</t></is></c><c r="B2" s="2" t="inlineStr"><is><t>Наложение на предмет в инвентаре, на земле в инвентаре, под курсором, в руках боевой панели, Уфопедии и других поддерживаемых экранах. Не для предметов на карте.</t></is></c><c r="C2" s="2" t="inlineStr"><is><t>Обработчик отсутствует</t></is></c></row><row r="3" ht="46" customHeight="1"><c r="A3" s="3" t="inlineStr"><is><t>items[].scripts.handOverlay</t></is></c><c r="B3" s="3" t="inlineStr"><is><t>Наложение на область руки, переносимого предмета или окна боеприпаса. В Уфопедии не вызывается.</t></is></c><c r="C3" s="3" t="inlineStr"><is><t>Обработчик отсутствует</t></is></c></row><row r="4" ht="46" customHeight="1"><c r="A4" s="2" t="inlineStr"><is><t>armors[].scripts.unitPaperdollOverlay</t></is></c><c r="B4" s="2" t="inlineStr"><is><t>Наложение на фигуру солдата в инвентаре.</t></is></c><c r="C4" s="2" t="inlineStr"><is><t>Обработчик отсутствует</t></is></c></row><row r="5" ht="46" customHeight="1"><c r="A5" s="3" t="inlineStr"><is><t>armors[].scripts.unitRankOverlay</t></is></c><c r="B5" s="3" t="inlineStr"><is><t>Наложение на область ранга/аватара выбранного юнита на боевой панели.</t></is></c><c r="C5" s="3" t="inlineStr"><is><t>Обработчик отсутствует</t></is></c></row><row r="6" ht="46" customHeight="1"><c r="A6" s="2" t="inlineStr"><is><t>armors[].scripts.unitSpriteOverlay</t></is></c><c r="B6" s="2" t="inlineStr"><is><t>Наложение на юнита на карте с учётом видимости, отсечения и освещения. Область 32×40 на часть юнита.</t></is></c><c r="C6" s="2" t="inlineStr"><is><t>Обработчик отсутствует</t></is></c></row><row r="7" ht="46" customHeight="1"><c r="A7" s="3" t="inlineStr"><is><t>armors[].scripts.unitSkillIconOverlay</t></is></c><c r="B7" s="3" t="inlineStr"><is><t>Наложение на кнопку навыков выбранного солдата (34×33). Перед рисованием восстанавливается исходная кнопка.</t></is></c><c r="C7" s="3" t="inlineStr"><is><t>Исходный skillIconSprite, без наложения</t></is></c></row><row r="8" ht="46" customHeight="1"><c r="A8" s="2" t="inlineStr"><is><t>extended.scripts.&lt;имя события&gt;</t></is></c><c r="B8" s="2" t="inlineStr"><is><t>Глобальный обработчик любого из шести событий. Использует существующие offset и code.</t></is></c><c r="C8" s="2" t="inlineStr"><is><t>Глобальных обработчиков нет</t></is></c></row><row r="10" ht="80" customHeight="1"><c r="A10" s="2" t="inlineStr"><is><t>Новые обработчики scripts. extraSprites, files, width, height, singleImage, skillIconSprite, offset и code существовали ранее. SCP_*_INDICATOR — имена ресурсов. Размер кнопок SPICONS.DAT 34×33 задан в движке, отдельного реквизита размера кнопки нет.</t></is></c></row></sheetData><autoFilter ref="A1:C8"/><mergeCells count="1"><mergeCell ref="A10:C10"/></mergeCells></worksheet>
'@)
$writer.Dispose()
$entry=$zip.CreateEntry('xl/worksheets/sheet2.xml')
$writer=[IO.StreamWriter]::new($entry.Open(),[Text.UTF8Encoding]::new($false))
$writer.Write(@'
<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="62" customWidth="1"/><col min="2" max="2" width="88" customWidth="1"/><col min="3" max="3" width="45" customWidth="1"/></cols><sheetData><row r="1" ht="32" customHeight="1"><c r="A1" s="1" t="inlineStr"><is><t>Наименование</t></is></c><c r="B1" s="1" t="inlineStr"><is><t>Описание</t></is></c><c r="C1" s="1" t="inlineStr"><is><t>Значение по умолчанию</t></is></c></row><row r="2" ht="46" customHeight="1"><c r="A2" s="2" t="inlineStr"><is><t>overlay / SpriteOverlay</t></is></c><c r="B2" s="2" t="inlineStr"><is><t>Контекст рисования. Координаты локальные; выход за границы обрезается. Индекс палитры 0 прозрачен, 15 — чёрный.</t></is></c><c r="C2" s="2" t="inlineStr"><is><t>Пустое прозрачное наложение</t></is></c></row><row r="3" ht="46" customHeight="1"><c r="A3" s="3" t="inlineStr"><is><t>sprite / Sprite</t></is></c><c r="B3" s="3" t="inlineStr"><is><t>Указатель на загруженное изображение.</t></is></c><c r="C3" s="3" t="inlineStr"><is><t>Незаданный указатель — null</t></is></c></row><row r="4" ht="46" customHeight="1"><c r="A4" s="2" t="inlineStr"><is><t>render_context / InvSpriteContext</t></is></c><c r="B4" s="2" t="inlineStr"><is><t>Контекст экранов и штатных индикаторов в событиях предметов.</t></is></c><c r="C4" s="2" t="inlineStr"><is><t>Задаётся путём отрисовки</t></is></c></row><row r="5" ht="46" customHeight="1"><c r="A5" s="3" t="inlineStr"><is><t>unit_part</t></is></c><c r="B5" s="3" t="inlineStr"><is><t>Аргумент unitSpriteOverlay: часть большого юнита, не анатомическая часть тела.</t></is></c><c r="C5" s="3" t="inlineStr"><is><t>Задаётся движком; у обычного юнита 0</t></is></c></row><row r="6" ht="46" customHeight="1"><c r="A6" s="2" t="inlineStr"><is><t>shade</t></is></c><c r="B6" s="2" t="inlineStr"><is><t>Освещение в unitSpriteOverlay. Применяется движком при завершении наложения; повторная передача в blitShade затемнит дважды.</t></is></c><c r="C6" s="2" t="inlineStr"><is><t>Задаётся движком</t></is></c></row><row r="7" ht="46" customHeight="1"><c r="A7" s="3" t="inlineStr"><is><t>overlay.getWidth result</t></is></c><c r="B7" s="3" t="inlineStr"><is><t>Ширина области наложения в пикселях.</t></is></c><c r="C7" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="8" ht="46" customHeight="1"><c r="A8" s="2" t="inlineStr"><is><t>overlay.getHeight result</t></is></c><c r="B8" s="2" t="inlineStr"><is><t>Высота области наложения в пикселях.</t></is></c><c r="C8" s="2" t="inlineStr"><is><t>—</t></is></c></row><row r="9" ht="46" customHeight="1"><c r="A9" s="3" t="inlineStr"><is><t>overlay.blit sprite x y</t></is></c><c r="B9" s="3" t="inlineStr"><is><t>Рисует изображение без дополнительного затемнения. null пропускается.</t></is></c><c r="C9" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="10" ht="46" customHeight="1"><c r="A10" s="2" t="inlineStr"><is><t>overlay.blitCrop sprite x1 y1 x2 y2</t></is></c><c r="B10" s="2" t="inlineStr"><is><t>Рисует от (0,0), ограничивая область назначения прямоугольником. Правая и нижняя границы исключены.</t></is></c><c r="C10" s="2" t="inlineStr"><is><t>—</t></is></c></row><row r="11" ht="46" customHeight="1"><c r="A11" s="3" t="inlineStr"><is><t>overlay.blitShade sprite x y shade</t></is></c><c r="B11" s="3" t="inlineStr"><is><t>Рисует с затемнением 0…16; 16 даёт чёрный.</t></is></c><c r="C11" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="12" ht="46" customHeight="1"><c r="A12" s="2" t="inlineStr"><is><t>overlay.blitShadeRecolor sprite x y shade colorGroup</t></is></c><c r="B12" s="2" t="inlineStr"><is><t>Рисует с затемнением и перекраской в палитровый ряд 0…15.</t></is></c><c r="C12" s="2" t="inlineStr"><is><t>—</t></is></c></row><row r="13" ht="46" customHeight="1"><c r="A13" s="3" t="inlineStr"><is><t>overlay.drawNumber number x y width height color</t></is></c><c r="B13" s="3" t="inlineStr"><is><t>Рисует неотрицательное число. color — индекс палитры.</t></is></c><c r="C13" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="14" ht="46" customHeight="1"><c r="A14" s="2" t="inlineStr"><is><t>overlay.drawText text x y width height color</t></is></c><c r="B14" s="2" t="inlineStr"><is><t>Рисует текст текущим шрифтом; строка не переводится автоматически как ключ. В текущем unitSpriteOverlay не рисует: язык не передаётся.</t></is></c><c r="C14" s="2" t="inlineStr"><is><t>—</t></is></c></row><row r="15" ht="46" customHeight="1"><c r="A15" s="3" t="inlineStr"><is><t>overlay.drawLine x1 y1 x2 y2 color</t></is></c><c r="B15" s="3" t="inlineStr"><is><t>Линия, включая конечную точку.</t></is></c><c r="C15" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="16" ht="46" customHeight="1"><c r="A16" s="2" t="inlineStr"><is><t>overlay.drawRect x1 y1 x2 y2 color</t></is></c><c r="B16" s="2" t="inlineStr"><is><t>Заполненный прямоугольник. Правая и нижняя границы исключены.</t></is></c><c r="C16" s="2" t="inlineStr"><is><t>—</t></is></c></row><row r="17" ht="46" customHeight="1"><c r="A17" s="3" t="inlineStr"><is><t>overlay.drawCirc x y radius color</t></is></c><c r="B17" s="3" t="inlineStr"><is><t>Заполненный круг.</t></is></c><c r="C17" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="18" ht="46" customHeight="1"><c r="A18" s="2" t="inlineStr"><is><t>sprite.getWidth result</t></is></c><c r="B18" s="2" t="inlineStr"><is><t>Ширина изображения.</t></is></c><c r="C18" s="2" t="inlineStr"><is><t>—</t></is></c></row><row r="19" ht="46" customHeight="1"><c r="A19" s="3" t="inlineStr"><is><t>sprite.getHeight result</t></is></c><c r="B19" s="3" t="inlineStr"><is><t>Высота изображения.</t></is></c><c r="C19" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="20" ht="46" customHeight="1"><c r="A20" s="2" t="inlineStr"><is><t>rules.getNamedSprite result name</t></is></c><c r="B20" s="2" t="inlineStr"><is><t>Получает одиночное изображение по имени ресурса.</t></is></c><c r="C20" s="2" t="inlineStr"><is><t>При отсутствии — null</t></is></c></row><row r="21" ht="46" customHeight="1"><c r="A21" s="3" t="inlineStr"><is><t>rules.getSpriteFromSet result name index</t></is></c><c r="B21" s="3" t="inlineStr"><is><t>Получает кадр набора. Индекс загруженного набора должен учитывать смещение ресурсов мода.</t></is></c><c r="C21" s="3" t="inlineStr"><is><t>При отсутствии — null</t></is></c></row><row r="22" ht="46" customHeight="1"><c r="A22" s="2" t="inlineStr"><is><t>rules.getInterfaceElementColor result interface element</t></is></c><c r="B22" s="2" t="inlineStr"><is><t>Основной цвет элемента интерфейса.</t></is></c><c r="C22" s="2" t="inlineStr"><is><t>При отсутствии цвета/элемента — −1</t></is></c></row><row r="23" ht="46" customHeight="1"><c r="A23" s="3" t="inlineStr"><is><t>rules.getInterfaceElementColor2 result interface element</t></is></c><c r="B23" s="3" t="inlineStr"><is><t>Второй цвет элемента интерфейса.</t></is></c><c r="C23" s="3" t="inlineStr"><is><t>При отсутствии цвета/элемента — −1</t></is></c></row><row r="24" ht="46" customHeight="1"><c r="A24" s="2" t="inlineStr"><is><t>render_context.getContext result</t></is></c><c r="B24" s="2" t="inlineStr"><is><t>Возвращает битовую маску контекста.</t></is></c><c r="C24" s="2" t="inlineStr"><is><t>Задаётся движком</t></is></c></row><row r="25" ht="46" customHeight="1"><c r="A25" s="3" t="inlineStr"><is><t>render_context.isInContext result mask</t></is></c><c r="B25" s="3" t="inlineStr"><is><t>Пересечение с маской контекста. Проверять через neq result 0.</t></is></c><c r="C25" s="3" t="inlineStr"><is><t>—</t></is></c></row><row r="26" ht="46" customHeight="1"><c r="A26" s="2" t="inlineStr"><is><t>render_context.getRenderOptions result</t></is></c><c r="B26" s="2" t="inlineStr"><is><t>Маска разрешённых штатных индикаторов.</t></is></c><c r="C26" s="2" t="inlineStr"><is>